using ConjuntoInteligente.PbBridge.Services; using FluentAssertions;
namespace ConjuntoInteligente.PbBridge.Tests;
public sealed class MapperTests{private readonly PbMapper _mapper=new();
 [Fact] public void Order_is_mapped_with_all_fields(){var src=new CoreOrder("o-1","SRV-2026-000001","Falla luz","iluminacion","high","in_progress","Parqueadero 1","Zona 3","AST-1","resident","Apto 404","Eléctricos SAS",450_000,DateTimeOffset.Parse("2026-10-01T12:00:00Z"),DateTimeOffset.Parse("2026-10-01T13:00:00Z"),DateTimeOffset.Parse("2026-10-02T12:00:00Z"),"Sin luz","property-1","unit-1","resident-1","vendor-1");var dto=_mapper.ToPb(src);dto.Id.Should().Be("o-1");dto.Codigo.Should().Be("SRV-2026-000001");dto.Estado.Should().Be("in_progress");dto.Reporto.Should().Be("Apto 404 (resident)");dto.CostoCop.Should().Be(450_000);dto.PropertyId.Should().Be("property-1");dto.UnitId.Should().Be("unit-1");dto.ResidentId.Should().Be("resident-1");dto.VendorId.Should().Be("vendor-1");dto.CreadaEn.Should().EndWith("Z");dto.SlaVenceEn.Should().NotBeNull();}
 [Fact] public void Order_dates_are_iso_utc(){var src=new CoreOrder("o","c","t","x","high","scheduled","a","z",null,"system","sys",null,null,DateTimeOffset.Parse("2026-10-01T12:00:00-05:00"),DateTimeOffset.Parse("2026-10-01T12:00:00-05:00"),null,"");var dto=_mapper.ToPb(src);dto.CreadaEn.Should().Contain("Z");dto.CreadaEn.Should().StartWith("2026-10-01T17:");}
 [Fact] public void Resident_is_mapped_without_inventing_missing_balance(){var unitId=Guid.Parse("304c3cc3-1884-4db4-b288-edaa5a69c611");var src=new CoreResident("r-1","Torre 1","404","Apto 404","Ana","a@x.com","+57...",true,null,[unitId]);var dto=_mapper.ToPb(src);dto.Id.Should().Be("r-1");dto.Torre.Should().Be("Torre 1");dto.Unidad.Should().Be("Apto 404");dto.UnitIds.Should().ContainSingle().Which.Should().Be(unitId.ToString());dto.SaldoCop.Should().BeNull();}
 [Fact] public void Vendor_is_mapped(){var src=new CoreVendor("v-1","Eléctricos SAS","900123",["iluminacion"],"ACTIVE",true,4.5m);var dto=_mapper.ToPb(src);dto.Nombre.Should().Be("Eléctricos SAS");dto.Categorias.Should().ContainSingle().Which.Should().Be("iluminacion");dto.DocumentosVigentes.Should().BeTrue();}
}
